export function words(s: string): string[] {
  return s.split(/\s+/).filter(Boolean);
}

export function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function titleCase(s: string): string {
  return words(s).map(capitalize).join(" ");
}

export function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export function truncate(s: string, max: number): string {
  if (max <= 0) return "";
  return s.length <= max ? s : `${s.slice(0, max - 1)}…`;
}
import { expect, test } from "bun:test";
import { capitalize, slugify, titleCase, truncate, words } from "./text.ts";

test("words splits on whitespace", () => {
  expect(words("  a  b c ")).toEqual(["a", "b", "c"]);
});

test("capitalize uppercases the first character", () => {
  expect(capitalize("hello")).toBe("Hello");
  expect(capitalize("")).toBe("");
  expect(capitalize("éa")).toBe("Éa");
});

test("titleCase capitalizes each word", () => {
  expect(titleCase("hello big world")).toBe("Hello Big World");
  expect(titleCase("  a  b ")).toBe("A B");
});

test("slugify normalizes separators", () => {
  expect(slugify("  Hello, World!  ")).toBe("hello-world");
  expect(slugify("a--b")).toBe("a-b");
  expect(slugify("")).toBe("");
});

test("truncate respects its maximum length", () => {
  expect(truncate("hello world", 8)).toBe("hello w…");
  expect(truncate("hi", 8)).toBe("hi");
  expect(truncate("hello", 5)).toBe("hello");
  expect(truncate("hello", 0)).toBe("");
  expect(truncate("hello", -1)).toBe("");
  expect(truncate("hello", 1)).toBe("…");
});

